      for (let j = 0; j < m2.length; j++) { const b = m2[j], d = Math.round(b[7] * 10000) - Math.round(a[7] * 15000); if ((d === 50 || d === -50) && Math.round(a[7] * 1.5 * 100) === Math.round(b[7] * 100)) { fd = [a, b, d]; break; } }
